create or replace function public.configure_business_geofence(p_geofence_id uuid,p_radius_meters integer default null,p_notification_enabled boolean default null,p_notification_payload jsonb default null,p_active boolean default null) returns public.business_geofences language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_user uuid:=auth.uid(); v_geofence public.business_geofences; v_allowed boolean; v_payload jsonb; begin if v_user is null then raise exception 'authentication required'; end if; select exists(select 1 from public.business_geofences g left join public.business_members bm on bm.business_id=g.business_id and bm.user_id=v_user where g.id=p_geofence_id and (bm.role::text in ('owner','admin','manager') or public.is_platform_owner())) into v_allowed; if not v_allowed then raise exception 'business geofence authorization required'; end if; if p_radius_meters is not null and (p_radius_meters < 25 or p_radius_meters > 5000) then raise exception 'radius must be between 25 and 5000 meters'; end if; if p_notification_payload is not null then if jsonb_typeof(p_notification_payload) <> 'object' then raise exception 'notification payload must be a JSON object'; end if; v_payload=jsonb_build_object('title',nullif(trim(coalesce(p_notification_payload->>'title','')),''),'body',nullif(trim(coalesce(p_notification_payload->>'body','')),''),'trigger',coalesce(p_notification_payload->>'trigger','enter'),'cta',case when jsonb_typeof(p_notification_payload->'cta')='object' then p_notification_payload->'cta' else null end,'promotion_id',case when nullif(p_notification_payload->>'promotion_id','') is null then null else (p_notification_payload->>'promotion_id')::text end); end if; update public.business_geofences g set radius_meters=coalesce(p_radius_meters,g.radius_meters),notification_enabled=coalesce(p_notification_enabled,g.notification_enabled),notification_payload=coalesce(v_payload,g.notification_payload),active=coalesce(p_active,g.active) where g.id=p_geofence_id returning g.* into v_geofence; if not found then raise exception 'geofence not found'; end if; return v_geofence; end; $$; grant execute on function public.configure_business_geofence(uuid,integer,boolean,jsonb,boolean) to authenticated; revoke execute on function public.configure_business_geofence(uuid,integer,boolean,jsonb,boolean) from anon,public;
